<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">[zk: localhost:2181(</span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;">CONNECTED</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">) 1] set /config </span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">&quot;newconfig1&quot;</span></span>
